BEGIN;
CREATE FUNCTION pg_temp.cc_assert(ok boolean,label text) RETURNS void LANGUAGE plpgsql AS $$ BEGIN IF ok IS NOT TRUE THEN RAISE EXCEPTION 'FALLA checkout check: %',label;END IF;END $$;
INSERT INTO auth.users(id) VALUES('00000000-0000-0000-0000-00000000ae01'),('00000000-0000-0000-0000-00000000ae02');
INSERT INTO public.team_members(id,name,email,role,active) VALUES('00000000-0000-0000-0000-00000000ae01','Admin sintético CC','cc-admin@example.test','admin',true),('00000000-0000-0000-0000-00000000ae02','Limpieza sintética CC','cc-clean@example.test','cleaning',true);
INSERT INTO public.properties(id,name) VALUES('00000000-0000-0000-0000-00000000ae11','CC sintético');
INSERT INTO public.reservations(id,property_id,source,check_in,check_out,status) VALUES('00000000-0000-0000-0000-00000000ae21','00000000-0000-0000-0000-00000000ae11','direct',(clock_timestamp() AT TIME ZONE 'America/Bogota')::date-2,(clock_timestamp() AT TIME ZONE 'America/Bogota')::date,'confirmed');
INSERT INTO public.maintenance(id,property_id,title,description,priority,status,reported_by) VALUES('00000000-0000-0000-0000-00000000ae31','00000000-0000-0000-0000-00000000ae11','Huésped reportó platos faltantes','Comprobar disponibilidad, cantidad desconocida','normal','open','00000000-0000-0000-0000-00000000ae01');
CREATE TEMP TABLE cc_source AS SELECT to_jsonb(m) original,jsonb_build_object('id',m.id,'property_id',m.property_id,'title',m.title,'status',m.status,'priority',m.priority,'fingerprint',md5(coalesce(m.description,'')||chr(31)||coalesce(m.notes,''))) snap FROM public.maintenance m WHERE id='00000000-0000-0000-0000-00000000ae31';
CREATE TEMP TABLE cc_stay AS SELECT jsonb_build_object('id',id,'property_id',property_id,'check_in',check_in,'check_out',check_out) snap FROM public.reservations WHERE id='00000000-0000-0000-0000-00000000ae21';
GRANT SELECT ON cc_source,cc_stay TO authenticated;
SELECT pg_temp.cc_assert((SELECT count(*)=0 FROM public.checkout_check_prompts WHERE property_id='00000000-0000-0000-0000-00000000ae11'),'sin selección no hay aviso');
SET LOCAL ROLE authenticated;SET LOCAL request.jwt.claim.sub='00000000-0000-0000-0000-00000000ae01';
SELECT pg_temp.cc_assert((public.add_checkout_check('00000000-0000-0000-0000-00000000ae31',(SELECT snap FROM cc_source),'Contar platos disponibles sin asumir cantidad','00000000-0000-0000-0000-00000000ae41')->>'ok')::boolean,'selección explícita');
SELECT pg_temp.cc_assert((public.add_checkout_check('00000000-0000-0000-0000-00000000ae31',(SELECT snap FROM cc_source),'Contar platos disponibles sin asumir cantidad','00000000-0000-0000-0000-00000000ae41')->>'ok')::boolean,'reintento');
SELECT pg_temp.cc_assert((SELECT count(*)=1 FROM public.checkout_check_prompts WHERE source_id='00000000-0000-0000-0000-00000000ae31'),'no dup');
SET LOCAL request.jwt.claim.sub='00000000-0000-0000-0000-00000000ae02';
DO $$ BEGIN BEGIN PERFORM public.add_checkout_check('00000000-0000-0000-0000-00000000ae31',(SELECT snap FROM cc_source),'No autorizada selección nueva','00000000-0000-0000-0000-00000000ae42');RAISE EXCEPTION 'FALLA cleaning crea';EXCEPTION WHEN insufficient_privilege THEN NULL;END;END $$;
SELECT pg_temp.cc_assert((public.skip_checkout_check((SELECT id FROM public.checkout_check_prompts WHERE source_id='00000000-0000-0000-0000-00000000ae31'),'00000000-0000-0000-0000-00000000ae21',(SELECT snap FROM cc_stay),(SELECT snap FROM cc_source),'No hubo acceso al armario','00000000-0000-0000-0000-00000000ae43')->>'ok')::boolean,'omitir salida');
SELECT pg_temp.cc_assert((SELECT count(*)=1 FROM public.checkout_check_skips WHERE actor_id='00000000-0000-0000-0000-00000000ae02' AND reason='No hubo acceso al armario' AND created_at IS NOT NULL),'traza omisión');
SELECT pg_temp.cc_assert((SELECT to_jsonb(m)=(SELECT original FROM cc_source) FROM public.maintenance m WHERE id='00000000-0000-0000-0000-00000000ae31'),'mantenimiento intacto');
RESET ROLE;
UPDATE public.maintenance SET description='Nueva descripción del reporte' WHERE id='00000000-0000-0000-0000-00000000ae31';
SET LOCAL ROLE authenticated;SET LOCAL request.jwt.claim.sub='00000000-0000-0000-0000-00000000ae02';
SELECT pg_temp.cc_assert((public.skip_checkout_check((SELECT id FROM public.checkout_check_prompts WHERE source_id='00000000-0000-0000-0000-00000000ae31'),'00000000-0000-0000-0000-00000000ae21',(SELECT snap FROM cc_stay),(SELECT snap FROM cc_source),'No hubo acceso al armario','00000000-0000-0000-0000-00000000ae44')->>'ok')='false','descripción cambiada invalida');
ROLLBACK;
